function newestArtifactFor(u:UserRecord,kind:string){return newestMatch(u.artifacts.filter(artifact=>canonicalArtifactKind(artifact.kind)===kind&&acceptsEvidenceExtension(artifact.filename)&&(kind==='SAAR'||filenameIdentityMatches(artifact.filename,u))),kind,artifact=>artifact.filename)}
function statusFor(u:UserRecord,kind:string,asOf=new Date()):ComplianceStatus{const a=newestArtifactFor(u,kind);if(!a)return'Missing';const d=parseDate(a.filename);if(!d)return'Missing';if(kind==='SAAR')return'Current';const due=new Date(d);due.setUTCFullYear(due.getUTCFullYear()+1);return due<asOf?'Overdue':'Current'}
