 const[showCleanup,setShowCleanup]=useState(initialCleanupOpen),[archiveSelected,setArchiveSelected]=useState<string[]>([]),[zipSelected,setZipSelected]=useState<string[]>([]),[reworkSelected,setReworkSelected]=useState<string[]>(initialCleanupOpen?pending.reworkCandidates.map(candidate=>candidate.id):[]);
 const system=pending.systems.find(s=>s.id===pending.systemId),selectedDiscovered=discovered.filter(item=>item.included),validDiscovered=selectedDiscovered.every(item=>!!item.record.last&&!!item.record.first&&!!item.record.organization&&validEmail(item.record.email)&&(!needsElevatedRole(item.record.roles)||item.record.privilegedTypes.length>0));
 const eligibleArchiveIds=pending.archiveCandidates.filter(candidate=>!candidate.requiresCandidateId||approved.includes(candidate.requiresCandidateId)).map(candidate=>candidate.id),allArchivesSelected=eligibleArchiveIds.length>0&&eligibleArchiveIds.every(id=>archiveSelected.includes(id)),allZipsSelected=pending.zipCandidates.length>0&&pending.zipCandidates.every(candidate=>zipSelected.includes(candidate.id)),allReworkSelected=pending.reworkCandidates.length>0&&pending.reworkCandidates.every(candidate=>reworkSelected.includes(candidate.id));
