  {hasCleanup&&<div className="cleanup-prompt"><div><strong>{pending.reworkCandidates.length} Rework, {pending.archiveCandidates.length} Duplicate or Superseded, and {pending.zipCandidates.length} Matched Loose PDF File{pending.archiveCandidates.length+pending.zipCandidates.length+pending.reworkCandidates.length===1?'':'s'} Identified</strong><small>Sync only identified these files. No file was moved, compressed, or deleted.</small></div><button onClick={()=>{setShowCleanup(true);setReworkSelected(pending.reworkCandidates.map(candidate=>candidate.id))}}>Clean Up</button></div>}
